template.solver:
def solve(d):
    best = -1
    for A in range(1, 10):
        for L in range(1, 10):
            if L == A:
                continue
            for M in range(1, 10):
                if M == A or M == L:
                    continue
                for T in range(1, 10):
                    if T == A or T == L or T == M:
                        continue
                    N = A*100000 + L*10000 + M*1000 + A*100 + T*10 + A
                    if N % d == 0:
                        s = 3*A + L + M + T
                        if best < 0 or s < best:
                            best = s
    return best
